class Solution {
    public int maxUncrossedLines(int[] nums1,int[] nums2){
        int[][] dp=new int[nums1.length+1][nums2.length+1];
        for(int i=1;i<=nums1.length;i++)for(int j=1;j<=nums2.length;j++)dp[i][j]=nums1[i-1]==nums2[j-1]?dp[i-1][j-1]+1:Math.max(dp[i-1][j],dp[i][j-1]);
        return dp[nums1.length][nums2.length];
    }
}

code.kotlin:
class Solution {
    fun maxUncrossedLines(nums1:IntArray,nums2:IntArray):Int{
        val dp=Array(nums1.size+1){
            IntArray(nums2.size+1)
        };
        for(i in 1..nums1.size)for(j in 1..nums2.size)dp[i][j]=if(nums1[i-1]==nums2[j-1])dp[i-1][j-1]+1 else maxOf(dp[i-1][j],dp[i][j-1]);
        return dp[nums1.size][nums2.size]
    }
}

