class Solution {
    public: int maxUncrossedLines(vector<int>& nums1,vector<int>& nums2){
        vector<vector<int>> dp(nums1.size()+1,vector<int>(nums2.size()+1));
        for(int i=1;i<=(int)nums1.size();++i)for(int j=1;j<=(int)nums2.size();++j)dp[i][j]=nums1[i-1]==nums2[j-1]?dp[i-1][j-1]+1:max(dp[i-1][j],dp[i][j-1]);
        return dp.back().back();
    }
};
